package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.UTF8StreamJsonParser;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextFieldName.
 * Note: Since ReaderBasedJsonParser is a protected class and its constructor 
 * is complex, we use JsonFactory to create a parser that inherits its behavior.
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen1Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    private SerializableString sstr(String s) {
        return new SerializableString() {
            @Override
            public String toString() { return s; }
            @Override
            public String asUnquotedString() { return s; }
            @Override
            public String asQuotedString() { return "\"" + s + "\""; }
            @Override
            public char[] asQuotedChars() { return asQuotedString().toCharArray(); }
            @Override
            public String getValue() { return s; }
        };
    }

    @Test
    public void testNextFieldName_MatchSuccess() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(json);

        // Move to start of object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Test successful match
        boolean match = parser.nextFieldName(sstr("name"));
        assertTrue("Should return true when field name matches", match);

        // Verify we are now at the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_Mismatch() throws IOException {
        String json = "{\"age\":30}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Test mismatch
        boolean match = parser.nextFieldName(sstr("name"));
        assertFalse("Should return false when field name does not match", match);

        // The parser should still be at the field name token or handle it via _isNextTokenNameMaybe
        // In Jackson, if it returns false, the current token is usually the field name itself
        assertEquals(JsonToken.FIELD_NAME, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.getCurrentToken());

        // If current token is FIELD_NAME, nextFieldName returns false and skips to value
        boolean match = parser.nextFieldName(sstr("name"));
        assertFalse("Should return false if already at FIELD_NAME", match);

        // After returning false, it calls _nextAfterName(), so next token should be the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // In an empty object, the next token after START_OBJECT is END_OBJECT
        // nextFieldName will encounter END_OBJECT (INT_RCURLY)
        boolean match = parser.nextFieldName(sstr("any"));
        assertFalse(match);
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_EndOfArray() throws IOException {
        String json = "[]";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        // In an array, nextFieldName should trigger a mismatch error/logic
        // because nextFieldName is only valid in an Object context.
        try {
            parser.nextFieldName(sstr("any"));
            fail("Should have thrown exception because we are in an array");
        } catch (IOException e) {
            // Expected: _nextTokenNotInObject or _reportMismatchedEndMarker
        }
    }

    @Test
    public void testNextFieldName_EndOfStream() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());

        // Now at end of stream
        boolean match = parser.nextFieldName(sstr("any"));
        assertFalse(match);
        assertEquals(JsonToken.NOT_AVAILABLE, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_WhitespaceHandling() throws IOException {
        String json = "{   \"name\" : \"value\"}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        boolean match = parser.nextFieldName(sstr("name"));
        assertTrue(match);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_FastPathMatch() throws IOException {
        // This tests the logic: if (_inputBuffer[end] == '"') and the while loop match
        // We need a buffer large enough to satisfy (ptr + len + 4) < _inputEnd
        String json = "{\"target\":\"value\"}";
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // "target" is 6 chars. 6 + 4 = 10. 
        // The JSON string is long enough to satisfy the fast path check.
        boolean match = parser.nextFieldName(sstr("target"));
        assertTrue(match);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }
}
